-- Why the platform closed a join request. Generated by `prisma migrate diff --from-schema <schema before>
-- --to-schema schema.prisma --script` and read for DROP statements (there are none).
CREATE TYPE "JoinRequestCloseReason" AS ENUM ('REQUESTER_DEACTIVATED', 'TEAM_DEACTIVATED', 'ORGANIZATION_DEACTIVATED');

-- AlterTable
ALTER TABLE "team_join_requests" ADD COLUMN     "close_reason" "JoinRequestCloseReason";

